# IGV / UCSC-browser-style tracks with Gviz: ideogram + axis + gene models + data tracks (hg19)
suppressPackageStartupMessages({library(Gviz); library(TxDb.Hsapiens.UCSC.hg19.knownGene); library(org.Hs.eg.db); library(GenomicRanges); library(ChIPseeker)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE)))); options(ucscChromosomeNames = FALSE)
txdb <- TxDb.Hsapiens.UCSC.hg19.knownGene
pk <- readPeakFile(getSampleFiles()[[4]])   # ChIPseeker sample peaks (GEO, hg19)
chr <- "chr1"; st <- 1e6; en <- 3e6
gtr <- GeneRegionTrack(txdb, chromosome = chr, start = st, end = en, name = "UCSC genes", transcriptAnnotation = "symbol", collapseTranscripts = "meta", fill = "#253494")
sym <- mapIds(org.Hs.eg.db, gene(gtr), "SYMBOL", "ENTREZID"); symbol(gtr) <- ifelse(is.na(sym), gene(gtr), sym)
pks <- subsetByOverlaps(pk, GRanges(chr, IRanges(st, en)))
at <- AnnotationTrack(pks, name = "peaks", fill = "#e31a1c", col = NA); set.seed(1)
cov <- DataTrack(GRanges(chr, IRanges(seq(st, en - 5000, 5000), width = 5000), score = sapply(seq(st, en - 5000, 5000), function(x) sum(overlapsAny(pks, GRanges(chr, IRanges(x, width = 5000)))) * pmax(0, rnorm(1, 5, 1)))), name = "peak signal", type = "histogram", fill = "#41ab5d", col.histogram = NA)
ax <- GenomeAxisTrack(); bands <- data.frame(chrom = "chr1", chromStart = c(0, 2300000), chromEnd = c(2300000, 5300000), name = c("p36.33","p36.32"), gieStain = c("gneg","gpos25"))
id <- IdeogramTrack(genome = "hg19", chromosome = chr, bands = bands)
png("v1_igv_style_tracks.png", 1600, 900, res = 160); plotTracks(list(id, ax, cov, at, gtr), from = st, to = en, background.title = "#2b2b2b", sizes = c(1, 1.2, 2, .8, 4)); dev.off()
png("v2_zoom_gene_model.png", 1600, 700, res = 160)
g2 <- GeneRegionTrack(txdb, chromosome = chr, start = 1.33e6, end = 1.36e6, name = "transcripts", transcriptAnnotation = "transcript", fill = "#fd8d3c")
plotTracks(list(ax, g2, at), from = 1.33e6, to = 1.36e6, background.title = "darkblue"); dev.off()
png("v3_ucsc_style_dense.png", 1600, 600, res = 160)
plotTracks(list(ax, GeneRegionTrack(txdb, chromosome = chr, start = st, end = en, name = "genes", stacking = "dense", fill = "#08306b"), at), from = st, to = en, background.title = "white", col.title = "black", col.axis = "black", fontcolor.title = "black"); dev.off()
